+func TestPrompt_LatestClarificationFollowsTitle(t *testing.T) {
+	trig := Trigger{
+		Source:     "github_issue",
+		IssueTitle: "Widen the cache",
+		IssueBody:  "The cache is too small.",
+		IssueComments: []IssueComment{
+			{Author: "a", Body: "first thought"},
+			{Author: "b", Body: "use 64 MiB, not 32"},
+		},
+	}
+	got, err := Build("plan", trig)
+	if err != nil {
+		t.Fatal(err)
+	}
+	title := strings.Index(got, "Title: Widen the cache")
+	latest := strings.Index(got, "Latest clarification: use 64 MiB, not 32")
+	if title < 0 || latest < title {
+		t.Fatalf("Latest clarification line missing or before the title:\n%s", got)
+	}
+}
